-- ==============================================================================
-- DeV Fit: Seed Database Ricettario (104 Ricette: 52 Fit + 52 Sgarro)
-- Pochi ingredienti, basso livello di difficoltà, valori nutrizionali autentici
-- Run this in the Supabase SQL Editor:
-- https://supabase.com/dashboard/project/_/sql
-- ==============================================================================

-- 1. Creazione tabella recipes se non esiste
CREATE TABLE IF NOT EXISTS recipes (
  id TEXT PRIMARY KEY,
  title TEXT NOT NULL,
  type TEXT NOT NULL CHECK (type IN ('fit', 'sgarro')),
  prep_time INTEGER NOT NULL,
  difficulty TEXT NOT NULL,
  equipment TEXT[] DEFAULT '{}',
  ingredients TEXT[] DEFAULT '{}',
  instructions TEXT[] DEFAULT '{}',
  calories NUMERIC NOT NULL,
  protein NUMERIC NOT NULL,
  carbs NUMERIC NOT NULL,
  fat NUMERIC NOT NULL,
  image_url TEXT,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- 2. Inserimento / Upsert di tutte le 104 ricette
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  type = EXCLUDED.type,
  prep_time = EXCLUDED.prep_time,
  difficulty = EXCLUDED.difficulty,
  equipment = EXCLUDED.equipment,
  ingredients = EXCLUDED.ingredients,
  instructions = EXCLUDED.instructions,
  calories = EXCLUDED.calories,
  protein = EXCLUDED.protein,
  carbs = EXCLUDED.carbs,
  fat = EXCLUDED.fat,
  image_url = EXCLUDED.image_url;

-- Indici per velocizzare le ricerche
CREATE INDEX IF NOT EXISTS idx_recipes_type ON recipes(type);
CREATE INDEX IF NOT EXISTS idx_recipes_difficulty ON recipes(difficulty);

SELECT 'Seed ricettario completato con successo: 104 ricette inserite nel database.' AS status;
