INSERT INTO recipes (id, title, type, prep_time, difficulty, equipment, ingredients, instructions, calories, protein, carbs, fat, image_url)
VALUES
  ('fit-01-pancake-avena', 'Pancake Proteici all''Avena (3 Ingredienti)', 'fit', 12, 'Facile', ARRAY['Padella antiaderente', 'Ciotola', 'Frusta a mano']::TEXT[], ARRAY['120g Albume d''uovo', '40g Farina d''avena aromatizzata o neutra', '1 cucchiaino raso di Lievito per dolci']::TEXT[], ARRAY['Sbatti energicamente l''albume con la farina d''avena e il lievito fino ad ottenere una pastella liscia.', 'Scalda una padella antiaderente a fiamma medio-bassa e versa metà impasto.', 'Attendi la comparsa delle bollicine in superficie (circa 90 secondi), gira il pancake e cuoci altri 60 secondi.', 'Ripeti per il secondo pancake e servi caldo.']::TEXT[], 215, 21, 26, 3, 'https://images.unsplash.com/photo-1567620905732-2d1ec7ab7445?auto=format&fit=crop&w=600&q=80'),
  ('fit-02-mugcake-cacao', 'Mug Cake Proteica al Microonde al Cioccolato', 'fit', 5, 'Facile', ARRAY['Tazza da colazione (mug)', 'Forno a Microonde', 'Forchetta']::TEXT[], ARRAY['1 Banana matura media', '1 Uovo intero', '15g Cacao amaro in polvere', '15g Proteine in polvere o farina d''avena']::TEXT[], ARRAY['In una tazza schiaccia accuratamente la banana con una forchetta fino a ridurla in purea.', 'Aggiungi l''uovo, il cacao amaro e le proteine/avena, mescolando bene per non lasciare grumi.', 'Cuoci nel microonde a 750W per circa 2 minuti fino a quando la tortina si gonfia.', 'Lascia intiepidire 1 minuto e gusta direttamente dalla tazza con un cucchiaino.']::TEXT[], 265, 22, 32, 6, 'https://images.unsplash.com/photo-1587314168485-3236d6710814?auto=format&fit=crop&w=600&q=80'),
  ('fit-03-overnight-oats', 'Overnight Oats Proteico ai Frutti di Bosco', 'fit', 5, 'Facile', ARRAY['Barattolo di vetro con coperchio', 'Cucchiaio', 'Frigorifero']::TEXT[], ARRAY['50g Fiocchi d''avena baby', '100g Yogurt greco 0%', '100ml Bevanda di soia o mandorla senza zuccheri', '50g Mirtilli o frutti di bosco freschi']::TEXT[], ARRAY['Nel barattolo unisci i fiocchi d''avena, il latte vegetale e lo yogurt greco mescolando con cura.', 'Chiudi ermeticamente e riponi in frigorifero per tutta la notte (almeno 6 ore).', 'Al mattino l''avena avrà assorbito i liquidi diventando cremosa: guarnisci con i mirtilli freschi e servi freddo.']::TEXT[], 310, 23, 42, 5, 'https://images.unsplash.com/photo-1517673132405-a56a62b18caf?auto=format&fit=crop&w=600&q=80'),
  ('fit-04-yogurt-burro-arachidi', 'Coppa Fit Yogurt Greco, Burro d''Arachidi & Cannella', 'fit', 3, 'Facile', ARRAY['Ciotola da dessert', 'Cucchiaio']::TEXT[], ARRAY['200g Yogurt greco 0% grassi', '20g Burro d''arachidi 100% naturale', '1 cucchiaino di Cannella in polvere', 'Gocce di dolcificante stevia (opzionale)']::TEXT[], ARRAY['Versa lo yogurt greco in una ciotola.', 'Scalda il burro d''arachidi per 10 secondi nel microonde per renderlo fluido e colalo a filo sopra lo yogurt.', 'Spolvera generosamente con la cannella in polvere e gusta immediatamente.']::TEXT[], 255, 26, 9, 11, 'https://images.unsplash.com/photo-1488477181946-6428a0291777?auto=format&fit=crop&w=600&q=80'),
  ('fit-05-porridge-banana-cacao', 'Porridge Caldo Cremoso Cacao e Banana', 'fit', 8, 'Facile', ARRAY['Pentolino antiaderente', 'Cucchiaio di legno']::TEXT[], ARRAY['45g Fiocchi d''avena', '180ml Acqua o latte scremato', '10g Cacao amaro in polvere', '1/2 Banana a fettine']::TEXT[], ARRAY['In un pentolino versa l''avena, il cacao e il liquido scelto.', 'Cuoci a fiamma moderata mescolando continuamente per 4-5 minuti fino a consistenza densa e vellutata.', 'Trasferisci in una ciotola e disponi in superficie le fettine di banana.']::TEXT[], 240, 9, 43, 4, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=600&q=80'),
  ('fit-06-waffle-albume', 'Waffle Fit Croccanti all''Albume', 'fit', 10, 'Facile', ARRAY['Piastra per waffle (o padella)', 'Ciotola', 'Frusta']::TEXT[], ARRAY['100g Albume d''uovo pastorizzato', '35g Farina d''avena neutra', '1 pizzico di Bicarbonato o lievito', 'Qualche goccia di aroma vaniglia']::TEXT[], ARRAY['Accendi la piastra per waffle per farla scaldare bene.', 'In una ciotola unisci albume, farina d''avena, lievito e vaniglia mescolando energicamente.', 'Spennella la piastra con un velo d''olio di cocco, versa la pastella e chiudi per circa 4 minuti finché dorato.']::TEXT[], 185, 18, 23, 2, 'https://images.unsplash.com/photo-1506084868230-bb9d95c24759?auto=format&fit=crop&w=600&q=80'),
  ('fit-07-mousse-cioccolato-ricotta', 'Mousse Espressa Cioccolato & Ricotta Light', 'fit', 5, 'Facile', ARRAY['Ciotola', 'Frusta o cucchiaio']::TEXT[], ARRAY['150g Ricotta vaccina light', '15g Cacao amaro di qualità', '1 cucchiaino di Miele o sciroppo d''agave']::TEXT[], ARRAY['Lavora la ricotta in una ciotola con una frusta per renderla cremosa e setosa.', 'Aggiungi il cacao amaro setacciato e il cucchiaino di miele.', 'Mescola fino a completo assorbimento e riponi in frigo 10 minuti prima di servire.']::TEXT[], 210, 16, 14, 9, 'https://images.unsplash.com/photo-1551024709-8f23befc6f87?auto=format&fit=crop&w=600&q=80'),
  ('fit-08-chia-pudding-cocco', 'Chia Pudding al Latte di Cocco e Frutti Rossi', 'fit', 5, 'Facile', ARRAY['Bicchiere di vetro', 'Cucchiaino', 'Frigo']::TEXT[], ARRAY['25g Semi di chia neri', '150ml Latte di cocco leggero o bevanda alla mandorla', '40g Lamponi o fragole fresche']::TEXT[], ARRAY['Versa i semi di chia nel bicchiere assieme al latte vegetale.', 'Mescola bene per 1 minuto per evitare che i semi si depositino sul fondo.', 'Lascia riposare in frigo almeno 3 ore (i semi formeranno un gel vellutato). Guarnisci con lamponi.']::TEXT[], 195, 6, 12, 12, 'https://images.unsplash.com/photo-1511690656952-34342bb7c2f2?auto=format&fit=crop&w=600&q=80'),
  ('fit-09-biscotti-banana-avena', 'Biscotti Fit 2 Ingredienti Senza Zucchero', 'fit', 18, 'Facile', ARRAY['Teglia da forno', 'Carta da forno', 'Ciotola']::TEXT[], ARRAY['2 Banane mature', '100g Fiocchi d''avena integrali']::TEXT[], ARRAY['Preriscalda il forno a 180°C.', 'Schiaccia le banane in una ciotola con una forchetta e incorpora i fiocchi d''avena fino a formare un composto sodo.', 'Forma 6 dischetti con le mani e adagiali su una teglia rivestita di carta forno.', 'Inforna per 12-14 minuti finché i bordi risultano dorati.']::TEXT[], 130, 4, 26, 2, 'https://images.unsplash.com/photo-1558961363-fa8fdf82db35?auto=format&fit=crop&w=600&q=80'),
  ('fit-10-french-toast-fit', 'French Toast Proteico alla Cannella', 'fit', 8, 'Facile', ARRAY['Padella antiaderente', 'Piatto fondo', 'Spatola']::TEXT[], ARRAY['2 Fette di pane di segale o bauletto integrale (60g)', '100g Albume d''uovo', '1 cucchiaino di Cannella in polvere']::TEXT[], ARRAY['Sbatti l''albume con la cannella in un piatto fondo.', 'Immergi ciascuna fetta di pane per 10 secondi per lato facendola ben impregnare.', 'Cuoci su padella antiaderente rovente a fuoco medio per 2-3 minuti per lato finché dorato e croccante.']::TEXT[], 205, 18, 28, 2, 'https://images.unsplash.com/photo-1484723091739-0045615eb40f?auto=format&fit=crop&w=600&q=80'),
  ('fit-11-protein-fluff-frutti-bosco', 'Protein Fluff Soffice ai Frutti di Bosco', 'fit', 6, 'Facile', ARRAY['Sbattitore elettrico con fruste', 'Ciotola capiente']::TEXT[], ARRAY['150g Frutti di bosco surgelati', '30g Proteine whey o isolate alla vaniglia', '50ml Latte parzialmente scremato o vegetale freddissimo']::TEXT[], ARRAY['Frulla brevemente i frutti di bosco congelati nel mixer con il latte per sminuzzarli.', 'Aggiungi le proteine in polvere nella ciotola con le fruste elettriche.', 'Monta ad alta velocità per 4 minuti: il volume quadruplicherà diventando una nuvola soffice come gelato.']::TEXT[], 210, 28, 18, 2, 'https://images.unsplash.com/photo-1563805042-7684c019e1cb?auto=format&fit=crop&w=600&q=80'),
  ('fit-12-crepes-albume-avena', 'Crepes Leggere di Solo Albume e Avena', 'fit', 10, 'Facile', ARRAY['Crepiera o padella larga', 'Frusta a mano']::TEXT[], ARRAY['120g Albume d''uovo', '30g Farina d''avena', '30ml Acqua']::TEXT[], ARRAY['Mescola l''albume con la farina e l''acqua fino a formare una pastella fluida.', 'Ungi leggermente una padella larga e scaldala a fuoco medio.', 'Versa l''impasto ruotando la padella per stenderlo sottile. Cuoci 1 minuto per lato.', 'Farcisci a piacere con ricotta magra o frutta fresca.']::TEXT[], 170, 17, 20, 2, 'https://images.unsplash.com/photo-1519676867240-f03562e64548?auto=format&fit=crop&w=600&q=80'),
  ('fit-13-yogurt-noci-miele', 'Bowl Greca con Noci del Brasile e Miele', 'fit', 2, 'Facile', ARRAY['Ciotola', 'Cucchiaio']::TEXT[], ARRAY['180g Yogurt greco autentico 0% grassi', '15g Noci sgusciate', '1 cucchiaino di Miele biologico']::TEXT[], ARRAY['Disponi lo yogurt greco denso al centro della ciotola.', 'Sbriciola grossolanamente le noci con le mani in superficie.', 'Completa colando il filo di miele e gusta subito.']::TEXT[], 235, 20, 12, 10, 'https://images.unsplash.com/photo-1488477181946-6428a0291777?auto=format&fit=crop&w=600&q=80'),
  ('fit-14-barrette-avena-burro-arachidi', 'Barrette Proteiche No-Bake Avena e Arachidi', 'fit', 10, 'Facile', ARRAY['Ciotola', 'Stampo rettangolare', 'Frigorifero']::TEXT[], ARRAY['100g Fiocchi d''avena', '60g Burro d''arachidi naturale', '30g Miele o sciroppo d''acero', '15g Gocce di cioccolato fondente 85%']::TEXT[], ARRAY['In una ciotola ammorbidisci il burro d''arachidi con il miele.', 'Unisci l''avena e le gocce di cioccolato, compattando il composto con il dorso di un cucchiaio.', 'Stendi l''impasto nello stampo foderato di carta forno e lascia solidificare in freezer per 30 minuti.', 'Taglia in 4 barrette pronte per lo snack.']::TEXT[], 240, 8, 28, 11, 'https://images.unsplash.com/photo-1622484216802-995a5f4d8961?auto=format&fit=crop&w=600&q=80'),
  ('fit-15-pollo-limone-rosmarino', 'Petto di Pollo Scottato al Limone e Rosmarino', 'fit', 12, 'Facile', ARRAY['Padella antiaderente', 'Pinza da cucina', 'Spremiagrumi']::TEXT[], ARRAY['200g Petto di pollo a fette', '1 Limone biologico (succo e scorza)', '1 rametto di Rosmarino fresco', '1 cucchiaino di Olio extravergine d''oliva']::TEXT[], ARRAY['Scalda la padella con il cucchiaino di olio e gli aghi di rosmarino.', 'Adagia il petto di pollo e scotta a fiamma vivace per 3 minuti per lato.', 'Versa il succo di limone nella padella, copri e lascia sfumare per 2 minuti creando un sughetto cremoso.', 'Regola di sale e pepe e servi subito.']::TEXT[], 260, 46, 2, 7, 'https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?auto=format&fit=crop&w=600&q=80'),
  ('fit-16-salmone-zucchine-airfryer', 'Trancio di Salmone con Zucchine in Friggitrice ad Aria', 'fit', 14, 'Facile', ARRAY['Friggitrice ad aria (o Forno)', 'Tagliere']::TEXT[], ARRAY['180g Filetto di salmone fresco', '1 Zucchina media a rondelle', '1 cucchiaino di Olio EVO, sale e pepe rosa']::TEXT[], ARRAY['Condisci le rondelle di zucchina con il cucchiaino di olio, sale e pepe.', 'Posiziona il trancio di salmone e le zucchine nel cestello della friggitrice ad aria.', 'Cuoci a 180°C per 12-14 minuti fino a quando la crosticina del salmone risulta croccante e la polpa morbida.']::TEXT[], 380, 36, 4, 22, 'https://images.unsplash.com/photo-1467003909585-2f8a72700288?auto=format&fit=crop&w=600&q=80'),
  ('fit-17-omelette-spinaci', 'Omelette Proteica agli Spinaci Baby', 'fit', 8, 'Facile', ARRAY['Padella antiaderente', 'Ciotola', 'Forchetta']::TEXT[], ARRAY['1 Uovo intero', '100g Albume d''uovo', '50g Spinacino fresco da insalata', '1 cucchiaino di Olio EVO']::TEXT[], ARRAY['Fai appassire gli spinaci in padella con una goccia d''olio per 1 minuto.', 'Sbatti l''uovo intero con l''albume, un pizzico di sale e pepe.', 'Versa le uova sopra gli spinaci, copri con un coperchio a fiamma dolce per 3 minuti, quindi piega a mezzaluna.']::TEXT[], 175, 20, 2, 8, 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=600&q=80'),
  ('fit-18-polpette-tonno-ricotta', 'Polpettine di Tonno e Ricotta al Forno (4 Ingredienti)', 'fit', 20, 'Facile', ARRAY['Teglia da forno', 'Ciotola', 'Carta forno']::TEXT[], ARRAY['160g Tonno al naturale sgocciolato', '100g Ricotta vaccina magra', '1 Uovo intero', '30g Pangrattato integrale']::TEXT[], ARRAY['In una ciotola unisci il tonno ben strizzato, la ricotta, l''uovo e un pizzico di sale.', 'Impasta con le mani e forma delle polpettine grandi come una noce, rotolandole nel pangrattato.', 'Disponi su una teglia e inforna a 190°C per 15 minuti finché sono dorate e croccanti esternamente.']::TEXT[], 340, 45, 18, 9, 'https://images.unsplash.com/photo-1529042410759-befb1204b468?auto=format&fit=crop&w=600&q=80'),
  ('fit-19-bowl-basmati-pollo-avocado', 'Fit Bowl con Riso Basmati, Pollo e Avocado', 'fit', 15, 'Facile', ARRAY['Pentolino', 'Padella', 'Bowl capiente']::TEXT[], ARRAY['60g Riso Basmati', '150g Petto di pollo a bocconcini', '40g Avocado a fettine', '1 cucchiaino di Salsa di soia a basso contenuto di sodio']::TEXT[], ARRAY['Lessa il riso basmati in acqua salata per 10 minuti e scolalo.', 'Scotta i bocconcini di pollo in padella antiaderente rovente per 5 minuti fino a doratura.', 'Componi la bowl disponendo il riso, il pollo caldo e l''avocado a ventaglio, terminando con la salsa di soia.']::TEXT[], 430, 39, 50, 8, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=600&q=80'),
  ('fit-20-spaghetti-zucchine-gamberi', 'Zoodles (Spaghetti di Zucchine) con Gamberi e Lime', 'fit', 10, 'Facile', ARRAY['Spiralizzatore per verdure o pelapatate', 'Padella']::TEXT[], ARRAY['2 Zucchine medie spiralizzate', '150g Code di gamberi sgusciate', '1 spicchio d''Aglio', 'Succo di 1/2 Lime e 1 cucchiaino di Olio EVO']::TEXT[], ARRAY['In una padella rosola l''aglio con l''olio, aggiungi i gamberi e cuoci per 2-3 minuti.', 'Unisci gli spaghetti di zucchine a crudo e salta tutto insieme a fiamma vivace per soli 2 minuti.', 'Spremi il succo di lime fresco e servi subito con verdure croccanti al dente.']::TEXT[], 210, 32, 8, 6, 'https://images.unsplash.com/photo-1551183053-bf91a1d81141?auto=format&fit=crop&w=600&q=80'),
  ('fit-21-tagliata-manzo-rucola-grana', 'Tagliata di Manzo con Rucola e Scaglie di Grana', 'fit', 10, 'Facile', ARRAY['Bisteccaia o padella in ghisa', 'Tagliere', 'Coltello affilato']::TEXT[], ARRAY['200g Taglio magro di manzo (controfiletto o noce)', '40g Rucola fresca', '20g Grana Padano o Parmigiano a scaglie', '1 cucchiaino di Olio EVO e gocce di glassa balsamica']::TEXT[], ARRAY['Scalda la piastra in ghisa al punto di fumo.', 'Cuoci la carne per 2 minuti per lato per una cottura media al sangue.', 'Fai riposare la carne 2 minuti sul tagliere, affettala a striscioline oblique e servila su un letto di rucola e scaglie di grana.']::TEXT[], 340, 48, 2, 15, 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=600&q=80'),
  ('fit-22-merluzzo-pomodoro-origano', 'Cuori di Merluzzo alla Mediterranea', 'fit', 15, 'Facile', ARRAY['Padella con coperchio', 'Cucchiaio']::TEXT[], ARRAY['200g Filetti di merluzzo', '120g Polpa di pomodoro fine', '1 cucchiaino di Capperi dissalati', 'Origano secco e 1 cucchiaino di Olio EVO']::TEXT[], ARRAY['In una padella versa la polpa di pomodoro, i capperi e un filo d''olio.', 'Adagia i cuori di merluzzo nella salsa e cospargi con abbondante origano.', 'Copri con coperchio e lascia cuocere a fuoco lento per 10-12 minuti finché il pesce si sfalda teneramente.']::TEXT[], 215, 38, 5, 5, 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?auto=format&fit=crop&w=600&q=80'),
  ('fit-23-wrap-tacchino-hummus', 'Wrap Integrale Veloce Tacchino ed Hummus', 'fit', 5, 'Facile', ARRAY['Padella per scaldare il wrap', 'Tagliere']::TEXT[], ARRAY['1 Piadina o tortilla 100% integrale (60g)', '80g Fesa di tacchino al naturale affettata', '30g Hummus di ceci', 'Qualche foglia di insalata croccante o spinacino']::TEXT[], ARRAY['Scalda la piadina 30 secondi per lato su padella calda per renderla flessibile.', 'Spalma l''hummus al centro della piadina.', 'Aggiungi la fesa di tacchino e le foglie di insalata, arrotola stretto e taglia a metà in diagonale.']::TEXT[], 290, 26, 32, 6, 'https://images.unsplash.com/photo-1626700051175-6818013e1d4f?auto=format&fit=crop&w=600&q=80'),
  ('fit-24-insalata-ceci-tonno-cipolla', 'Insalata Rustica di Ceci, Tonno e Cipolla Rossa', 'fit', 5, 'Facile', ARRAY['Ciotola capiente', 'Scolapasta']::TEXT[], ARRAY['150g Ceci cotti in barattolo (sciacquati)', '110g Tonno al naturale sgocciolato', '1/4 di Cipolla rossa di Tropea a fettine sottili', '1 cucchiaino di Olio EVO e prezzemolo']::TEXT[], ARRAY['Sciacqua bene i ceci sotto l''acqua fredda e trasferiscili in una ciotola.', 'Unisci il tonno sgranato e la cipolla rossa affettata sottilmente.', 'Condisci con il cucchiaino di olio, un pizzico di sale e prezzemolo fresco, mescola e gusta subito.']::TEXT[], 345, 37, 32, 7, 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=600&q=80'),
  ('fit-25-vellutata-zucca-carote', 'Vellutata Detox Zucca e Carote al Rosmarino', 'fit', 20, 'Facile', ARRAY['Pentola', 'Frullatore ad immersione (minipimer)']::TEXT[], ARRAY['250g Zucca mondata a cubetti', '150g Carote a rondelle', '250ml Brodo vegetale leggero', '1 cucchiaino di Olio EVO e rosmarino']::TEXT[], ARRAY['Metti zucca e carote in una pentola con il brodo caldo e il rametto di rosmarino.', 'Cuoci con coperchio per 15 minuti finché le verdure sono morbidissime.', 'Rimuovi il rosmarino, frulla con il minipimer fino a crema densa e vellutata e rifinisci con un filo d''olio a crudo.']::TEXT[], 155, 4, 28, 4, 'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=600&q=80'),
  ('fit-26-riso-venere-salmone-zucchine', 'Riso Venere Nero con Salmone e Zucchine Saltate', 'fit', 20, 'Facile', ARRAY['Pentolino', 'Padella antiaderente']::TEXT[], ARRAY['60g Riso Venere integrale', '120g Salmone fresco a cubetti', '1 Zucchina piccola a cubetti', '1 cucchiaino di Olio EVO']::TEXT[], ARRAY['Lessa il riso venere per circa 18 minuti e scolalo.', 'In padella scotta i dadini di salmone e le zucchine con un cucchiaino d''olio per 5 minuti.', 'Unisci il riso nero in padella, salta a fiamma vivace per 1 minuto e servi profumato.']::TEXT[], 430, 30, 46, 14, 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=600&q=80'),
  ('fit-27-uova-strapazzate-pomodorini', 'Uova Strapazzate Morbide con Pomodorini Datterini', 'fit', 7, 'Facile', ARRAY['Padella antiaderente', 'Spatola in silicone', 'Ciotolina']::TEXT[], ARRAY['2 Uova intere + 50g Albume', '6 Pomodorini datterini a metà', 'Qualche foglia di Basilico fresco', '1 cucchiaino di Olio EVO']::TEXT[], ARRAY['In una padella calda fai appassire i datterini nell''olio per 2 minuti schiacciandoli leggermente.', 'Sbatti uova e albume con un pizzico di sale e versali nella padella a fuoco medio-basso.', 'Muovi costantemente con la spatola per 2 minuti creando fiocchi morbidi e cremosi. Spegni e unisci il basilico.']::TEXT[], 230, 21, 4, 14, 'https://images.unsplash.com/photo-1586190848861-99aa4a171e90?auto=format&fit=crop&w=600&q=80'),
  ('fit-28-tartare-salmone-avocado', 'Tartare di Salmone Fresco, Avocado e Lime', 'fit', 10, 'Facile', ARRAY['Tagliere', 'Coltello affilato', 'Coppapasta (opzionale)']::TEXT[], ARRAY['150g Filetto di salmone abbattuto per crudo', '50g Avocado maturo a cubetti', 'Succo di 1/2 Lime e semi di sesamo']::TEXT[], ARRAY['Taglia il salmone e l''avocado a piccoli cubetti regolari con un coltello ben affilato.', 'Condisci il salmone in una ciotola con succo di lime, un pizzico di sale e semi di sesamo.', 'Impiatta con un coppapasta posizionando la base di avocado e sopra la tartare di salmone marinato.']::TEXT[], 335, 31, 4, 22, 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?auto=format&fit=crop&w=600&q=80'),
  ('fit-29-tartare-manzo-limone', 'Battuta al Coltello di Manzo con Limone ed Erba Cipollina', 'fit', 8, 'Facile', ARRAY['Tagliere', 'Coltello da chef']::TEXT[], ARRAY['180g Scamone o fesa di manzo freschissima di prima scelta', '1 cucchiaino di Olio EVO', 'Succo di 1/3 di Limone fresco', 'Fili di Erba cipollina fresca tagliuzzata']::TEXT[], ARRAY['Batti la carne al coltello finemente senza sfilacciarla.', 'Condisci al momento con il cucchiaino di olio EVO, fior di sale, pepe nero macinato fresco e il succo di limone.', 'Mescola con una forchetta, decora con erba cipollina e gusta fredda.']::TEXT[], 250, 40, 0, 9, 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=600&q=80'),
  ('fit-30-pasta-integrale-tonno-limone', 'Spaghetti Integrali Espresso Tonno e Limone', 'fit', 12, 'Facile', ARRAY['Pentola', 'Padella per saltare', 'Grattugia']::TEXT[], ARRAY['70g Spaghetti integrali', '100g Tonno al naturale sgocciolato', 'Scorza e succo di 1/2 Limone biologico', '1 cucchiaino di Olio EVO e prezzemolo']::TEXT[], ARRAY['Lessa la pasta in abbondante acqua salata.', 'In una padella intiepidisci il tonno al naturale con il cucchiaino d''olio e 2 cucchiai di acqua di cottura della pasta.', 'Scola gli spaghetti al dente direttamente in padella, manteca a fuoco spento con succo e scorza di limone e prezzemolo.']::TEXT[], 360, 32, 48, 5, 'https://images.unsplash.com/photo-1621996346565-e3d5d628169e?auto=format&fit=crop&w=600&q=80'),
  ('fit-31-bocconcini-pollo-curry', 'Bocconcini di Pollo al Curry Leggero (3 Ingredienti)', 'fit', 12, 'Facile', ARRAY['Padella antiaderente', 'Cucchiaio di legno']::TEXT[], ARRAY['200g Petto di pollo a dadini', '1 cucchiaio colmo di Polvere di Curry dolce', '60ml Latte parzialmente scremato o latte di cocco light', '1 cucchiaino di Olio EVO']::TEXT[], ARRAY['Scalda la padella con l''olio e rosola i bocconcini di pollo per 4 minuti a fuoco vivo.', 'Sciogli il curry nel latte e versalo sopra il pollo.', 'Abbassa la fiamma e lascia cuocere 3 minuti finché il liquido si restringe in una deliziosa cremina speziata.']::TEXT[], 285, 47, 3, 9, 'https://images.unsplash.com/photo-1589302168068-964664d93dc0?auto=format&fit=crop&w=600&q=80'),
  ('fit-32-burger-lenticchie', 'Burger Vegano di Lenticchie e Avena', 'fit', 15, 'Facile', ARRAY['Mixer o forchetta', 'Padella antiaderente']::TEXT[], ARRAY['200g Lenticchie lesse ben scolate', '30g Farina d''avena', '1 cucchiaino di Paprika dolce e rosmarino tritato']::TEXT[], ARRAY['Schiaccia le lenticchie con una forchetta lasciando qualche pezzo intero per la consistenza.', 'Unisci la farina d''avena e le spezie, impastando fino a formare un burger compatto.', 'Cuoci su padella calda con un velo d''olio per 4 minuti per lato finché dorato e croccante.']::TEXT[], 250, 17, 38, 3, 'https://images.unsplash.com/photo-1520072959219-c595dc870360?auto=format&fit=crop&w=600&q=80'),
  ('fit-33-shakshuka-fit', 'Shakshuka Fit: Uova in Purgatorio al Pomodoro', 'fit', 12, 'Facile', ARRAY['Padella antiaderente con coperchio', 'Cucchiaio']::TEXT[], ARRAY['2 Uova fresche medie', '180g Polpa o passata di pomodoro rustica', '1 spicchio d''Aglio e peperoncino a piacere', 'Origano fresco']::TEXT[], ARRAY['In una padella scalda l''aglio e aggiungi la passata di pomodoro con un pizzico di sale e origano per 4 minuti.', 'Crea due piccoli incavi nella salsa col cucchiaio e sgusciaci dentro le due uova.', 'Copri con il coperchio e lascia cuocere a fuoco dolce per 4-5 minuti finché l''albume è sodo e il tuorlo morbido.']::TEXT[], 195, 15, 10, 10, 'https://images.unsplash.com/photo-1590412200988-a436970781fa?auto=format&fit=crop&w=600&q=80'),
  ('fit-34-insalata-greca-light', 'Insalata Greca Fit con Feta Light e Cetrioli', 'fit', 6, 'Facile', ARRAY['Insalatiera', 'Coltello']::TEXT[], ARRAY['80g Feta DOP in versione Light (12% grassi)', '1 Cetriolo medio sbucciato a rondelle', '100g Pomodori da insalata a spicchi', '1 cucchiaino di Olio EVO e origano secco']::TEXT[], ARRAY['Taglia il cetriolo e i pomodori e riponili nell''insalatiera.', 'Taglia la feta light a cubetti e aggiungila sopra le verdure.', 'Condisci con il cucchiaino di olio EVO, una spolverata generosa di origano e servi fresco e dissetante.']::TEXT[], 230, 17, 9, 14, 'https://images.unsplash.com/photo-1540420773420-3366772f4999?auto=format&fit=crop&w=600&q=80'),
  ('fit-35-pollo-patate-dolci', 'Bocconcini di Pollo e Patate Dolci alla Paprika', 'fit', 20, 'Facile', ARRAY['Friggitrice ad aria o Teglia da forno']::TEXT[], ARRAY['180g Petto di pollo a tocchetti', '120g Patata dolce americana a cubetti', '1 cucchiaino di Paprika dolce o affumicata', '1 cucchiaino di Olio EVO']::TEXT[], ARRAY['Taglia pollo e patata dolce a cubi di dimensioni simili.', 'Mescola in una ciotola con l''olio, la paprika e un pizzico di sale.', 'Cuoci in airfryer a 190°C per 16 minuti scuotendo il cestello a metà cottura.']::TEXT[], 330, 42, 26, 6, 'https://images.unsplash.com/photo-1532550907401-a500c9a57435?auto=format&fit=crop&w=600&q=80'),
  ('fit-36-hummus-ceci-espresso', 'Hummus Veloce di Ceci Fatto in Casa (4 Ingredienti)', 'fit', 5, 'Facile', ARRAY['Mixer o frullatore']::TEXT[], ARRAY['200g Ceci cotti in barattolo (sciacquati)', '15g Tahina (pasta di sesamo)', 'Succo di 1/2 Limone', '1 cucchiaino di Olio EVO e 30ml acqua fredda']::TEXT[], ARRAY['Metti tutti gli ingredienti nel bicchiere del mixer.', 'Frulla per 2 minuti ad alta velocità aggiungendo l''acqua fredda poco alla volta fino a renderlo liscio e spumoso.', 'Servi con bastoncini di carota o crostini di segale.']::TEXT[], 295, 14, 32, 12, 'https://images.unsplash.com/photo-1577906096429-f73c2c312435?auto=format&fit=crop&w=600&q=80'),
  ('fit-37-tortino-patate-tonno', 'Tortino Espresso Patate Schiacciate e Tonno', 'fit', 12, 'Facile', ARRAY['Padella antiaderente', 'Forchetta']::TEXT[], ARRAY['150g Patata precedentemente lessata', '100g Tonno al naturale', '1 Uovo intero', 'Prezzemolo tritato e sale']::TEXT[], ARRAY['Schiaccia la patata lessa con la forchetta assieme al tonno e all''uovo fino a creare una pasta densa.', 'Scalda la padella con un velo d''olio e versa il composto schiacciandolo a forma di rosti/frittella spessa.', 'Cuoci a fiamma media 4 minuti per lato finché crea una crosticina dorata.']::TEXT[], 290, 34, 26, 6, 'https://images.unsplash.com/photo-1541832676-9b763b0239ab?auto=format&fit=crop&w=600&q=80'),
  ('fit-38-bistecca-cavolfiore', 'Steak di Cavolfiore Arrostita alle Spezie', 'fit', 15, 'Facile', ARRAY['Padella in ghisa o Forno']::TEXT[], ARRAY['2 Fette spesse di cavolfiore intero (250g)', '1 cucchiaino di Olio EVO', '1/2 cucchiaino di Curcuma e paprika affumicata', 'Sale grosso']::TEXT[], ARRAY['Spennella le bistecche di cavolfiore con l''olio miscelato alle spezie.', 'Adagia su piastra caldissima e cuoci 6 minuti per lato con un coperchio per far ammorbidire l''interno.', 'Servi ben abbrustolito come contorno o piatto leggero ad altissimo potere saziante.']::TEXT[], 95, 5, 11, 4, 'https://images.unsplash.com/photo-1568584711075-3d021a7c3ca3?auto=format&fit=crop&w=600&q=80'),
  ('fit-39-spiedini-pollo-peperoni', 'Spiedini di Pollo e Peperoni Grigliati', 'fit', 15, 'Facile', ARRAY['Spiedini di legno', 'Bisteccaia o Piastra']::TEXT[], ARRAY['200g Petto di pollo a cubotti', '1 Peperone rosso a quadretti', '1 cucchiaino di Olio EVO e origano']::TEXT[], ARRAY['Infila negli spiedini alternando bocconcini di pollo e falde di peperone.', 'Spennella con l''olio ed erbe aromatiche.', 'Griglia su piastra rovente per 10 minuti ruotando su tutti e 4 i lati finché il pollo è ben cotto.']::TEXT[], 260, 46, 6, 6, 'https://images.unsplash.com/photo-1532550907401-a500c9a57435?auto=format&fit=crop&w=600&q=80'),
  ('fit-40-straccetti-vitello-rucola', 'Straccetti di Manzo Magro con Rucola Saltata', 'fit', 8, 'Facile', ARRAY['Padella antiaderente', 'Pinza']::TEXT[], ARRAY['180g Straccetti di vitellone magro', '50g Rucola fresca', '1 cucchiaino di Olio EVO e gocce di aceto balsamico']::TEXT[], ARRAY['Scalda la padella a fiamma altissima con l''olio.', 'Butta gli straccetti e salta velocemente per soli 2 minuti affinché rimangano teneri e succosi.', 'Spegni il fuoco, butta la rucola che appassirà col calore residuo, spruzza con aceto balsamico e servi.']::TEXT[], 245, 39, 1, 9, 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=600&q=80'),
  ('fit-41-gamberi-zenzero-limone', 'Gamberi al Vapore con Zenzero Fresco e Limone', 'fit', 8, 'Facile', ARRAY['Cestello per vapore o Padella', 'Tagliere']::TEXT[], ARRAY['200g Gamberoni o code di gambero', '1 radice di Zenzero fresco a fettine', '1 Limone a rondelle', 'Un pizzico di sale e prezzemolo']::TEXT[], ARRAY['Disponi i gamberi nel cestello sopra le fette di limone e lo zenzero.', 'Cuoci a vapore per circa 4-5 minuti finché diventano opachi e rosati.', 'Condisci con il succo di limone fresco e gusta subito leggeri e profumatissimi.']::TEXT[], 170, 36, 2, 2, 'https://images.unsplash.com/photo-1559742811-822863cb4cb7?auto=format&fit=crop&w=600&q=80'),
  ('fit-42-piadina-avena-bresaola', 'Piadina Fit all''Avena con Bresaola e Rucola', 'fit', 10, 'Facile', ARRAY['Padella antiaderente', 'Ciotola']::TEXT[], ARRAY['45g Farina d''avena istantanea', '80ml Acqua tiepida e pizzico di sale', '60g Bresaola della Valtellina IGP', 'Un ciuffo di Rucola']::TEXT[], ARRAY['Mescola farina d''avena, acqua e sale fino a una pastella omogenea.', 'Versa in padella calda stendendo a disco e cuoci 2 minuti per lato.', 'Farcisci con bresaola e rucola fresca, piega a portafoglio e gusta croccante.']::TEXT[], 260, 29, 28, 4, 'https://images.unsplash.com/photo-1626700051175-6818013e1d4f?auto=format&fit=crop&w=600&q=80'),
  ('fit-43-tofu-croccante-airfryer', 'Tofu Croccante alla Soia in Friggitrice ad Aria', 'fit', 14, 'Facile', ARRAY['Friggitrice ad aria', 'Ciotola']::TEXT[], ARRAY['180g Tofu al naturale compatto', '1 cucchiaio di Salsa di soia a basso sale', '1 cucchiaino di Amido di mais (maizena)']::TEXT[], ARRAY['Asciuga il tofu con carta assorbente e taglialo a cubetti da 1.5cm.', 'Mescola con la soia e spolvera con la maizena (che creerà la crosta croccante).', 'Cuoci in airfryer a 200°C per 12 minuti scuotendo a metà cottura.']::TEXT[], 235, 26, 6, 12, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=600&q=80'),
  ('fit-44-mini-frittatine-piselli', 'Muffin di Frittata con Piselli ed Albume', 'fit', 18, 'Facile', ARRAY['Stampo per muffin in silicone', 'Forno o Friggitrice ad aria']::TEXT[], ARRAY['150g Albume d''uovo', '1 Uovo intero', '60g Piselli fini cotti a vapore', '15g Parmigiano grattugiato']::TEXT[], ARRAY['Sbatti albume, uovo, sale e parmigiano.', 'Distribuisci i piselli nei pirottini per muffin e versa il composto d''uovo sopra.', 'Inforna a 180°C per 15 minuti finché sono gonfi e dorati.']::TEXT[], 225, 25, 9, 9, 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=600&q=80'),
  ('fit-45-calamari-piastra-prezzemolo', 'Calamari Grigliati al Salmoriglio di Limone', 'fit', 10, 'Facile', ARRAY['Bisteccaia o padella in ghisa']::TEXT[], ARRAY['220g Calamari freschi puliti', 'Succo di 1 Limone ed erbe fresche (prezzemolo, aglio)', '1 cucchiaino di Olio EVO']::TEXT[], ARRAY['Incidi la superficie dei calamari a griglia senza tagliarli del tutto.', 'Cuoci su piastra caldissima per 2 minuti per lato (non di più per non indurirli).', 'Irrora con l''emulsione di limone, aglio tritato, prezzemolo e olio.']::TEXT[], 220, 38, 3, 6, 'https://images.unsplash.com/photo-1534422298391-e4f8c172dddb?auto=format&fit=crop&w=600&q=80'),
  ('fit-46-couscous-verdure-pollo', 'Cous Cous Veloce con Pollo e Zucchine', 'fit', 10, 'Facile', ARRAY['Ciotola con piattino per coprire', 'Padella']::TEXT[], ARRAY['60g Cous cous precotto', '120g Bocconcini di petto di pollo', '1 Zucchina piccola grattugiata a fori larghi', '1 cucchiaino di Olio EVO']::TEXT[], ARRAY['Versa il cous cous in una ciotola con 70ml di acqua bollente salata, copri e lascia gonfiare per 5 minuti.', 'In padella cuoci il pollo e la zucchina grattugiata con l''olio per 5 minuti.', 'Sgrana il cous cous con una forchetta, unisci il pollo e mescola.']::TEXT[], 375, 36, 46, 5, 'https://images.unsplash.com/photo-1512621776951-a57141f2eefd?auto=format&fit=crop&w=600&q=80'),
  ('fit-47-fusi-pollo-airfryer', 'Fusi di Pollo Senza Pelle Croccanti alle Spezie', 'fit', 22, 'Facile', ARRAY['Friggitrice ad aria']::TEXT[], ARRAY['2 Fusi di pollo spellati (circa 250g crudi)', '1 cucchiaino di Rosmarino tritato, aglio in polvere e paprika', 'Sale grosso']::TEXT[], ARRAY['Massaggia i fusi di pollo asciutti con le spezie e il sale.', 'Disponi nel cestello dell''airfryer a 195°C.', 'Cuoci per 20 minuti girandoli a metà cottura fino a formare una crosticina deliziosa senza grassi aggiunti.']::TEXT[], 290, 44, 1, 12, 'https://images.unsplash.com/photo-1598515214211-89d3c73ae83b?auto=format&fit=crop&w=600&q=80'),
  ('fit-48-poke-salmone-edamame', 'Mini Poke Bowl Salmone, Riso ed Edamame', 'fit', 12, 'Facile', ARRAY['Pentolino', 'Bowl']::TEXT[], ARRAY['50g Riso per sushi o Basmati', '100g Salmone crudo abbattuto a cubi', '40g Edamame sgranati cotti a vapore', '1 cucchiaino di Salsa di soia e semi di sesamo']::TEXT[], ARRAY['Cuoci il riso e lascialo intiepidire.', 'Disponi il riso nella ciotola, affianca il salmone fresco e gli edamame verdi.', 'Condisci con soia e una pioggia di sesamo tostato.']::TEXT[], 380, 32, 42, 10, 'https://images.unsplash.com/photo-1546069901-ba9599a7e63c?auto=format&fit=crop&w=600&q=80'),
  ('fit-49-crema-ricotta-mirtilli', 'Crema di Ricotta Soffice ai Mirtilli Caldi', 'fit', 4, 'Facile', ARRAY['Ciotolina', 'Microonde']::TEXT[], ARRAY['160g Ricotta vaccina fresca', '60g Mirtilli freschi o surgelati', 'Scorza grattugiata di Limone']::TEXT[], ARRAY['Scalda i mirtilli al microonde per 40 secondi finché rilasciano il loro succo naturale.', 'Lavora la ricotta con la scorza di limone fino a renderla spumosa.', 'Versa i mirtilli caldi sulla ricotta creando un contrasto caldo-freddo favoloso.']::TEXT[], 215, 14, 14, 11, 'https://images.unsplash.com/photo-1511690656952-34342bb7c2f2?auto=format&fit=crop&w=600&q=80'),
  ('fit-50-bocconcini-tacchino-salvia', 'Bocconcini di Tacchino alla Salvia e Vino Bianco', 'fit', 10, 'Facile', ARRAY['Padella antiaderente', 'Cucchiaio']::TEXT[], ARRAY['200g Fesa di tacchino a bocconcini', '5 Foglie di Salvia fresca', '40ml Vino bianco secco per sfumare', '1 cucchiaino di Olio EVO']::TEXT[], ARRAY['In padella rosola il tacchino con le foglie di salvia e l''olio a fiamma viva per 3 minuti.', 'Sfuma con il vino bianco lasciando evaporare l''alcol per 2 minuti creando un delizioso fondo di cottura.', 'Regola di sale e pepe e servi tenerissimo.']::TEXT[], 250, 48, 1, 5, 'https://images.unsplash.com/photo-1604908176997-125f25cc6f3d?auto=format&fit=crop&w=600&q=80'),
  ('fit-51-vellutata-zucchine-menta', 'Vellutata Fredda o Calda Zucchine e Menta', 'fit', 12, 'Facile', ARRAY['Pentola', 'Minipimer']::TEXT[], ARRAY['350g Zucchine verdi a pezzi', '50g Formaggio fresco spalmabile light o yogurt greco', 'Foglioline di Menta fresca', '1 cucchiaino di Olio EVO']::TEXT[], ARRAY['Cuoci le zucchine in 200ml di acqua salata per 8 minuti.', 'Aggiungi il formaggio spalmabile light, la menta e frulla finemente fino ad ottenere una vellutata verde brillante.', 'Rifinisci con un filo d''olio a crudo.']::TEXT[], 140, 7, 12, 7, 'https://images.unsplash.com/photo-1547592166-23ac45744acd?auto=format&fit=crop&w=600&q=80'),
  ('fit-52-avocado-egg-boat', 'Barchetta di Avocado al Forno con Uovo', 'fit', 15, 'Facile', ARRAY['Teglia da forno o Airfryer']::TEXT[], ARRAY['1/2 Avocado maturo scavato leggermente al centro', '1 Uovo medio', 'Sale, pepe e fiocchi di peperoncino']::TEXT[], ARRAY['Adagia il mezzo avocado in una teglietta in modo che rimanga stabile.', 'Rompi l''uovo direttamente nella cavità dell''avocado.', 'Inforna a 190°C (o airfryer a 180°C) per 12-14 minuti finché l''albume è rappreso e il tuorlo cremoso.']::TEXT[], 230, 9, 6, 20, 'https://images.unsplash.com/photo-1525351484163-7529414344d8?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-01-smash-burger', 'Double Smash Cheeseburger con Bacon Croccante', 'sgarro', 15, 'Facile', ARRAY['Piastra in ghisa o padella pesante', 'Spatola robusta metallica']::TEXT[], ARRAY['1 Brioche bun per hamburger', '200g Macinato di manzo (80/20)', '2 fette di Formaggio Cheddar', '2 fette di Bacon affumicato']::TEXT[], ARRAY['Tosta le due metà del bun sulla piastra calda con un velo di burro.', 'Forma due polpette da 100g. Scalda la piastra al massimo e schiacciale con forza con la spatola fino a renderle piatte e sottili.', 'Cuoci 2 minuti a calore infernale finché si forma la crosticina bruna, gira, adagia il cheddar sopra per farlo fondere.', 'Rosola il bacon fino a renderlo croccante, componi il panino e addenta bollente.']::TEXT[], 880, 48, 36, 59, 'https://images.unsplash.com/photo-1568901346375-23c9450c58cd?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-02-pizza-napoletana-rustica', 'Pizza Margherita Verace con Bufala Campana', 'sgarro', 25, 'Medio', ARRAY['Forno al massimo o Fornetto pizza', 'Teglia o pietra']::TEXT[], ARRAY['1 Panetto di pasta pizza lievitata (250g)', '120g Mozzarella di bufala o fior di latte', '80g Passata di pomodoro San Marzano', 'Olio EVO e foglie di basilico fresco']::TEXT[], ARRAY['Stendi l''impasto con i polpastrelli dal centro verso l''esterno formando il cornicione.', 'Distribuisci la passata di pomodoro e un filo generoso d''olio EVO.', 'Inforna alla massima temperatura (250°C o più) per 8-10 minuti.', 'A metà cottura aggiungi la mozzarella di bufala a pezzi ben scolata e termina con basilico fresco all''uscita.']::TEXT[], 840, 32, 110, 28, 'https://images.unsplash.com/photo-1513104890138-7c749659a591?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-03-carbonara-romana', 'Carbonara Tradizionale Romana Autentica (5 Ingredienti)', 'sgarro', 15, 'Medio', ARRAY['Padella antiaderente', 'Ciotola', 'Pentola per pasta']::TEXT[], ARRAY['100g Spaghetti o Rigatoni trafilati al bronzo', '80g Guanciale di suino a listarelle', '2 Tuorli d''uovo freschissimi', '40g Pecorino Romano DOP grattugiato', 'Pepe nero in grani tostato e macinato']::TEXT[], ARRAY['Metti a bollire l''acqua per la pasta (sala con moderazione).', 'Rosola il guanciale a fiamma dolce nella padella senza olio finché è dorato e croccante fuori e morbido dentro. Tieni da parte il grasso fuso.', 'In una ciotola sbatti i tuorli con il pecorino romano e abbondante pepe nero fino a formare una crema densa (la "carbocrema").', 'Scola la pasta al dente nella padella con il grasso del guanciale, spegni il fuoco e unisci la carbocrema mantecando energicamente lontano dalla fiamma.']::TEXT[], 790, 34, 75, 38, 'https://images.unsplash.com/photo-1612874742237-6526221588e3?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-04-cacio-e-pepe', 'Tonnarelli Cacio e Pepe Espresso Cremosi', 'sgarro', 12, 'Medio', ARRAY['Pentola', 'Padella grande', 'Ciotola']::TEXT[], ARRAY['100g Tonnarelli o spaghetti alla chitarra', '70g Pecorino Romano DOP a media stagionatura', 'Pepe nero in grani pestato al mortaio']::TEXT[], ARRAY['Tosta il pepe nero pestato nella padella a fuoco medio finché sprigiona tutti i suoi profumi, poi aggiungi due mestoli di acqua di cottura della pasta ricca di amido.', 'In una ciotola stempera il pecorino con poca acqua di cottura fino ad ottenere una pasta cremosa senza grumi.', 'Scola la pasta al dente nella padella col pepe, togli dal fuoco e versa la crema di pecorino mescolando vigorosamente finché lega formando un''onda vellutata.']::TEXT[], 640, 30, 74, 24, 'https://images.unsplash.com/photo-1621996346565-e3d5d628169e?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-05-grilled-cheese-filante', 'Ultimate Grilled Cheese Sandwich Triplo Formaggio', 'sgarro', 8, 'Facile', ARRAY['Padella antiaderente', 'Spatola']::TEXT[], ARRAY['2 Fette spesse di pane rustico o pane in cassetta', '50g Formaggio Cheddar a fette', '40g Scamorza affumicata o Provola', '20g Burro a temperatura ambiente']::TEXT[], ARRAY['Imburra generosamente l''esterno di ciascuna fetta di pane.', 'Farcisci l''interno con il cheddar e la scamorza.', 'Cuoci in padella a fuoco medio-basso per 3-4 minuti per lato coprendo con un coperchio per far fondere completamente il cuore e rendere il pane croccante e dorato.']::TEXT[], 620, 26, 42, 38, 'https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-06-patatine-parmigiano-tartufo', 'Patatine Fritte Croccanti al Parmigiano e Tartufo', 'sgarro', 18, 'Facile', ARRAY['Friggitrice ad aria o Friggitrice', 'Ciotola grande']::TEXT[], ARRAY['250g Patate a fiammifero da friggere', '30g Parmigiano Reggiano grattugiato finemente', '1 cucchiaio di Olio al tartufo', 'Prezzemolo tritato e sale fino']::TEXT[], ARRAY['Friggi le patatine fino a renderle dorate e super croccanti.', 'Scolale e versale immediatamente caldissime nella ciotola.', 'Cospargi con il parmigiano, l''olio al tartufo e prezzemolo, scuotendo la ciotola per mantecarle in modo uniforme.']::TEXT[], 470, 12, 52, 24, 'https://images.unsplash.com/photo-1573080496219-bb080dd4f877?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-07-quesadilla-pollo-formaggio', 'Quesadilla Messicana Filante con Pollo e Salsa BBQ', 'sgarro', 10, 'Facile', ARRAY['Padella grande', 'Spatola']::TEXT[], ARRAY['2 Tortillas di farina di grano', '100g Formaggio filante (Gouda o Cheddar grattugiato)', '100g Pollo arrosto o grigliato sfilacciato', '2 cucchiai di Salsa BBQ o maionese piccante']::TEXT[], ARRAY['Adagia una tortilla in padella calda e ricoprila con formaggio, pollo sfilacciato e salsa BBQ.', 'Chiudi con la seconda tortilla e cuoci 3 minuti per lato a fiamma media finché il formaggio fila ed è ben dorata.', 'Taglia a 4 spicchi e gusta caldissima.']::TEXT[], 690, 44, 54, 32, 'https://images.unsplash.com/photo-1565299585323-38d6b0865b47?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-08-nachos-loaded-cheddar', 'Loaded Nachos al Forno con Cheddar e Jalapeños', 'sgarro', 10, 'Facile', ARRAY['Pirofila o teglia da forno']::TEXT[], ARRAY['150g Tortilla chips di mais salate', '120g Formaggio Cheddar fuso o grattugiato', 'Fettine di Jalapeños sott''aceto', '50g Panna acida o salsa guacamole per intingere']::TEXT[], ARRAY['Distribuisci i nachos nella pirofila in un unico strato generoso.', 'Copri interamente con il formaggio grattugiato e i jalapeños a rondelle.', 'Inforna a 200°C per 6 minuti finché il formaggio è completamente fuso e fa le bolle. Servi con panna acida.']::TEXT[], 820, 22, 78, 48, 'https://images.unsplash.com/photo-1513456852971-30c0b8199d4d?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-09-focaccia-barese', 'Focaccia Barese Croccante Pomodorini e Olive', 'sgarro', 25, 'Facile', ARRAY['Teglia tonda in alluminio o ferro', 'Forno']::TEXT[], ARRAY['300g Impasto per focaccia lievitato', '150g Pomodorini ciliegino schiacciati a mano', '10 Olive baresi o nere snocciolate', 'Olio EVO abbondante e origano']::TEXT[], ARRAY['Ungi generosamente la teglia con abbondante olio EVO e allarga l''impasto con le dita.', 'Affonda nell''impasto i pomodorini spaccandoli con le mani e le olive.', 'Irrora con altro olio EVO, origano e sale grosso, quindi inforna a 220°C per 20 minuti finché il fondo è croccante e dorato.']::TEXT[], 750, 18, 98, 32, 'https://images.unsplash.com/photo-1574071318508-1cdbab80d002?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-10-hot-dog-cipolla-caramellata', 'Hot Dog Newyorkese con Cipolle Caramellate e Senape', 'sgarro', 12, 'Facile', ARRAY['Padella antiaderente', 'Pinza']::TEXT[], ARRAY['1 Panino morbido per hot dog', '1 Wurstel di suino di prima qualità (100g)', '1 Cipolla bionda stufata con un filo di burro e zucchero', 'Senape dolce e cetriolini a rondelle']::TEXT[], ARRAY['Rosola la cipolla a fette con burro finché diventa dorata e caramellata.', 'Griglia il wurstel in padella facendogli formare le classiche striature dorate.', 'Apri il panino scaldato, inserisci il wurstel, ricopri con abbondante cipolla caramellata e senape.']::TEXT[], 540, 18, 42, 34, 'https://images.unsplash.com/photo-1619740455993-9e612b1af08a?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-11-pasta-amatriciana', 'Bucatini all''Amatriciana Ricca di Guanciale', 'sgarro', 18, 'Facile', ARRAY['Padella in ferro o antiaderente', 'Pentola per pasta']::TEXT[], ARRAY['100g Bucatini di semola', '80g Guanciale di Amatrice a bastoncini', '150g Pomodori pelati schiacciati a mano', '40g Pecorino Romano grattugiato e peperoncino']::TEXT[], ARRAY['Fai sudare il guanciale in padella con un pizzico di peperoncino fino a renderlo croccante, poi preleva i pezzi tenendoli da parte.', 'Versa i pelati nel grasso del guanciale e lascia restringere il sugo per 10 minuti.', 'Scola i bucatini al dente nel sugo, unisci il guanciale croccante e manteca con abbondante pecorino.']::TEXT[], 760, 28, 78, 37, 'https://images.unsplash.com/photo-1621996346565-e3d5d628169e?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-12-mozzarella-in-carrozza', 'Mozzarella in Carrozza Dorata Super Filante (4 Ingredienti)', 'sgarro', 12, 'Facile', ARRAY['Padella per friggere', 'Piatto fondo']::TEXT[], ARRAY['4 Fette di pane in cassetta (senza crosta)', '120g Mozzarella fior di latte ben asciutta', '2 Uova intere sbattute con un goccio di latte', 'Pangrattato e olio per friggere']::TEXT[], ARRAY['Farcisci due sandwich con le fette di mozzarella al centro premendo bene i bordi.', 'Passa i sandwich prima nell''uovo sbattuto sigillando i bordi e poi nel pangrattato.', 'Friggi in olio caldo a 170°C per 2 minuti per lato finché dorati e croccanti.']::TEXT[], 650, 28, 48, 38, 'https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-13-crocche-patate-provola', 'Crocchè Napoletani di Patate e Provola Affumicata', 'sgarro', 20, 'Facile', ARRAY['Pentola', 'Teglia o Friggitrice']::TEXT[], ARRAY['250g Patate a pasta gialla lesse schiacciate', '60g Provola affumicata a bastoncini', '1 Tuorlo d''uovo e 20g Parmigiano', 'Pangrattato e pepe']::TEXT[], ARRAY['Mescola le patate schiacciate con il tuorlo, il parmigiano, sale e abbondante pepe nero.', 'Prendi una porzione di impasto, inserisci un bastoncino di provola al centro e chiudi a cilindro.', 'Passa nel pangrattato e cuoci in friggitrice ad aria a 200°C per 12 minuti (oppure friggi).']::TEXT[], 430, 18, 45, 19, 'https://images.unsplash.com/photo-1573080496219-bb080dd4f877?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-14-chicken-nuggets-cornflakes', 'Crispy Chicken Nuggets ai Cornflakes Croccanti', 'sgarro', 15, 'Facile', ARRAY['Teglia o Friggitrice ad aria', 'Ciotola']::TEXT[], ARRAY['200g Petto di pollo macinato o a bocconcini', '50g Formaggio fresco spalmabile', '1 Uovo sbattuto', '40g Cornflakes sbriciolati a mano']::TEXT[], ARRAY['Impasta il pollo con il formaggio spalmabile e un pizzico di sale formando delle pepite.', 'Passa i nuggets nell''uovo e poi nei cornflakes sbriciolati premendo bene per farli aderire.', 'Cuoci in airfryer a 190°C per 12 minuti fino a doratura ultra croccante.']::TEXT[], 480, 46, 32, 18, 'https://images.unsplash.com/photo-1562967914-608f82629710?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-15-piadina-salsiccia-squacquerone', 'Piadina Romagnola con Salsiccia, Squacquerone e Rucola', 'sgarro', 10, 'Facile', ARRAY['Testo romagnolo o padella larga', 'Forchetta']::TEXT[], ARRAY['1 Piadina romagnola tradizionale (100g)', '1 Salsiccia di suino spellata e sbriciolata', '70g Squacquerone DOP', 'Un pugno di Rucola fresca']::TEXT[], ARRAY['In una padella scotta la salsiccia sbriciolata finché è ben rosolata e croccante.', 'Scalda la piadina sul testo per 1 minuto per lato girandola spesso.', 'Spalma lo squacquerone caldissimo, unisci la salsiccia e la rucola, piega a metà e addenta.']::TEXT[], 730, 30, 54, 44, 'https://images.unsplash.com/photo-1626700051175-6818013e1d4f?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-16-gnocchi-quattro-formaggi', 'Gnocchi di Patate ai Quattro Formaggi Ripassati al Forno', 'sgarro', 15, 'Facile', ARRAY['Pirofila da forno', 'Pentola']::TEXT[], ARRAY['200g Gnocchi di patate freschi', '40g Gorgonzola dolce', '40g Taleggio o Fontina a cubetti', '30g Parmigiano Reggiano grattugiato e 50ml latte']::TEXT[], ARRAY['In un pentolino fondi a fuoco dolce il gorgonzola, il taleggio e il latte fino a crema fluida.', 'Lessa gli gnocchi in acqua bollente salata e scolali appena salgono a galla.', 'Mescola gli gnocchi alla crema di formaggi, trasferisci in pirofila, cospargi di parmigiano e gratina al grill per 5 minuti.']::TEXT[], 690, 26, 68, 34, 'https://images.unsplash.com/photo-1551183053-bf91a1d81141?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-17-club-sandwich-classico', 'Club Sandwich Americano Classico a Tre Piani', 'sgarro', 12, 'Facile', ARRAY['Tostapane o Piastra', 'Coltello da pane', 'Stuzzicadenti lunghi']::TEXT[], ARRAY['3 Fette di pane bianco tostato', '80g Petto di tacchino o pollo alla piastra', '3 Fette di Bacon croccante', '1 Uovo all''occhio di bue, maionese e lattuga']::TEXT[], ARRAY['Tosta le fette di pane e spalmaci un velo di maionese.', 'Componi il primo piano con lattuga, pomodoro e tacchino; metti la seconda fetta e farcisci con uovo fritto e bacon croccante.', 'Chiudi con la terza fetta, infilza con due stuzzicadenti e taglia in due triangoli.']::TEXT[], 720, 42, 46, 40, 'https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-18-frittata-di-pasta', 'Frittata di Spaghetti Napoletana Ricca e Croccante', 'sgarro', 15, 'Facile', ARRAY['Padella antiaderente', 'Piatto piano per girare la frittata']::TEXT[], ARRAY['150g Spaghetti già cotti (anche avanzati)', '2 Uova intere grandi', '50g Provola o fior di latte a dadini', '30g Pancetta a cubetti e parmigiano']::TEXT[], ARRAY['Sbatti le uova con parmigiano, sale e pepe.', 'Unisci gli spaghetti, i cubetti di provola e la pancetta mescolando bene.', 'Scalda una padella con un filo d''olio, versa la pasta e cuoci 5 minuti a fuoco medio fino a crosticina dorata, gira col piatto e completa l''altro lato.']::TEXT[], 680, 30, 62, 34, 'https://images.unsplash.com/photo-1586190848861-99aa4a171e90?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-19-costine-maiale-bbq', 'Costine di Maiale Glassate in Salsa Barbecue Caramellata', 'sgarro', 30, 'Facile', ARRAY['Forno o Friggitrice ad aria', 'Pennello da cucina']::TEXT[], ARRAY['350g Costine di maiale (ribs)', '4 cucchiai di Salsa BBQ densa e affumicata', '1 cucchiaino di Miele e paprika dolce']::TEXT[], ARRAY['Massaggia le costine con sale e paprika.', 'Inforna a 180°C coperte con alluminio per 20 minuti per renderle tenere.', 'Spennella generosamente con il mix di salsa BBQ e miele, quindi passa sotto il grill a 210°C per 8 minuti fino a glassatura lucida e sfrigolante.']::TEXT[], 720, 42, 22, 52, 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-20-pasta-alla-gricia', 'Mezze Maniche alla Gricia con Guanciale Croccante', 'sgarro', 12, 'Facile', ARRAY['Padella in alluminio o ferro', 'Pentola']::TEXT[], ARRAY['100g Mezze maniche rigate', '80g Guanciale a fettine', '40g Pecorino Romano grattugiato', 'Pepe nero macinato fresco']::TEXT[], ARRAY['Fai sfrigolare il guanciale in padella senza grassi aggiunti fino a renderlo croccante.', 'Lessa la pasta al dente e scolala direttamente nella padella col guanciale e un mestolo d''acqua di cottura.', 'Spegni il fuoco, aggiungi il pecorino a pioggia e manteca saltando la pasta fino a creare un''emulsione cremosa.']::TEXT[], 730, 28, 74, 36, 'https://images.unsplash.com/photo-1621996346565-e3d5d628169e?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-21-panino-porchetta-scamorza', 'Panino Rustico con Porchetta Calda e Scamorza Fusa', 'sgarro', 8, 'Facile', ARRAY['Piastra elettrica o fornetto']::TEXT[], ARRAY['1 Rosetta o ciabattina croccante', '120g Porchetta d''Ariccia a fette con cotenna croccante', '50g Scamorza affumicata a fette']::TEXT[], ARRAY['Apri il panino a metà e adagia sul fondo le fette di scamorza affumicata.', 'Aggiungi la porchetta generosa con la sua croccante crosticina.', 'Chiudi e tosta sulla piastra calda per 4 minuti finché il pane è friabile e il formaggio cola fuso.']::TEXT[], 660, 36, 44, 38, 'https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-22-salsiccia-e-friarielli', 'Salsiccia e Friarielli (Cime di Rapa) Napoletana', 'sgarro', 18, 'Facile', ARRAY['Padella capiente', 'Coperchio']::TEXT[], ARRAY['2 Salsicce di suino campane a punta di coltello', '200g Friarielli o cime di rapa fresche pulite', '1 spicchio d''Aglio, peperoncino e 1 cucchiaio Olio EVO']::TEXT[], ARRAY['In padella fai rosolare le salsicce bucherellate con mezzo bicchiere d''acqua finché l''acqua evapora e dorano nel loro grasso.', 'Sposta le salsicce, nella stessa padella unisci aglio, olio e peperoncino, poi versa i friarielli crudi con coperchio per 8 minuti.', 'Riunisci salsicce e friarielli, salta a fiamma viva per 2 minuti e servi caldissimo.']::TEXT[], 640, 32, 6, 56, 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-23-pizza-fritta-montanara', 'Montanara Fritta Napoletana al Pomodoro e Parmigiano', 'sgarro', 15, 'Facile', ARRAY['Pentola o padella per friggere', 'Mestolo']::TEXT[], ARRAY['150g Pasta per pizza lievitata a dischetti', '60g Sugo di pomodoro ristretto al basilico', '25g Parmigiano Reggiano grattugiato', 'Olio per friggere e basilico fresco']::TEXT[], ARRAY['Scalda l''olio per friggere a 175°C.', 'Immergi il disco di pasta pizza che si gonfierà immediatamente formando una nuvola dorata (1 minuto per lato).', 'Scola su carta assorbente, metti un cucchiaio di sugo caldo al centro, parmigiano a pioggia e una foglia di basilico.']::TEXT[], 510, 14, 58, 26, 'https://images.unsplash.com/photo-1513104890138-7c749659a591?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-24-cotoletta-alla-milanese', 'Cotoletta alla Milanese Burrosa con Patatine', 'sgarro', 15, 'Facile', ARRAY['Padella grande', 'Piatti per panatura']::TEXT[], ARRAY['1 Costoletta o fetta di lonza di vitello (180g)', '1 Uovo sbattuto', '60g Pangrattato grosso di pane raffermo', '40g Burro chiarificato per friggere']::TEXT[], ARRAY['Passa la carne nell''uovo sbattuto e poi nel pangrattato premendo con il palmo della mano.', 'Fai sciogliere il burro chiarificato in padella fino a farlo spumeggiare.', 'Cuoci la cotoletta 3-4 minuti per lato nappandola con il burro fuso fino a renderla color nocciola e croccantissima.']::TEXT[], 680, 42, 32, 42, 'https://images.unsplash.com/photo-1562967914-608f82629710?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-25-mac-and-cheese', 'Mac and Cheese Cremoso Americano al Forno', 'sgarro', 18, 'Facile', ARRAY['Pentola', 'Teglia da forno']::TEXT[], ARRAY['100g Maccheroncini o cellentani', '60g Formaggio Cheddar grattugiato', '40g Mozzarella o Gouda', '80ml Panna da cucina o latte intero con 10g burro']::TEXT[], ARRAY['Lessa la pasta al dente in acqua salata.', 'In un pentolino scalda la panna con il burro e incorpora il cheddar finché fila liscio.', 'Mischia la pasta col formaggio fuso, versa in pirofila, cospargi con altra mozzarella e inforna a 200°C per 8 minuti fino a gratinatura dorata.']::TEXT[], 730, 26, 72, 38, 'https://images.unsplash.com/photo-1551183053-bf91a1d81141?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-26-burrito-supremo', 'Burrito Supremo con Macinato Speziato, Cheddar e Riso', 'sgarro', 15, 'Facile', ARRAY['Padella', 'Tagliere']::TEXT[], ARRAY['1 Tortilla maxi di grano (80g)', '120g Carne macinata di manzo cotta con spezie taco', '40g Fagioli neri o rossi', '40g Cheddar grattugiato e 1 cucchiaio salsa piccante']::TEXT[], ARRAY['Scalda la tortilla in padella per renderla morbida.', 'Disponi al centro la carne macinata saporita, i fagioli, il cheddar e la salsa.', 'Ripiega i lati verso l''interno e arrotola stretto; ripassa il rotolo in padella 1 minuto per lato per sigillarlo.']::TEXT[], 690, 38, 64, 32, 'https://images.unsplash.com/photo-1626700051175-6818013e1d4f?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-27-focaccia-recco-formaggio', 'Focaccia Tipo Recco al Formaggio Sottile e Caldissima', 'sgarro', 20, 'Medio', ARRAY['Teglia tonda', 'Forno caldissimo']::TEXT[], ARRAY['180g Pasta matta sottilissima (farina, acqua, olio)', '150g Crescenza o Stracchino fresco ligure', 'Olio EVO e sale grosso']::TEXT[], ARRAY['Tira due sfoglie di pasta sottili come veli di seta.', 'Fodera la teglia con la prima sfoglia e distribuisci ciuffi abbondanti di crescenza.', 'Copri con la seconda sfoglia, pizzica la pasta creando delle fessure, irrora d''olio e inforna a 250°C per 10 minuti finché si formano bolle croccanti.']::TEXT[], 680, 24, 62, 38, 'https://images.unsplash.com/photo-1574071318508-1cdbab80d002?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-28-filetto-maiale-bardato', 'Medaglioni di Filetto di Maiale Bardati con Pancetta', 'sgarro', 16, 'Facile', ARRAY['Padella antiaderente', 'Spago o stuzzicadenti']::TEXT[], ARRAY['200g Filetto di maiale a fette spesse', '4 fette di Pancetta tesa affumicata', '1 rametto di Rosmarino e 30ml vino bianco']::TEXT[], ARRAY['Avvolgi il bordo di ciascun medaglione di filetto con le fette di pancetta fermandole con uno stuzzicadenti.', 'Cuoci in padella a fiamma viva con rosmarino per 3 minuti per lato finché la pancetta è croccante.', 'Sfuma col vino bianco e servi con il gustoso sughero di fondo.']::TEXT[], 460, 44, 1, 30, 'https://images.unsplash.com/photo-1544025162-d76694265947?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-29-panzerotti-fritti', 'Panzerotto Pugliese Fritto con Pomodoro e Mozzarella', 'sgarro', 18, 'Facile', ARRAY['Pentola per friggere', 'Forchetta per sigillare']::TEXT[], ARRAY['1 dischetto di Pasta lievitata (100g)', '50g Mozzarella fior di latte tritata e strizzata', '30g Passata di pomodoro densa, origano e sale', 'Olio per friggere']::TEXT[], ARRAY['Farcisci il centro del disco con mozzarella, pomodoro e origano.', 'Ripiega a mezzaluna e sigilla i bordi schiacciando bene con i rebbi della forchetta.', 'Tuffa nell''olio bollente per 2 minuti finché gonfio, dorato e profumato.']::TEXT[], 430, 14, 46, 22, 'https://images.unsplash.com/photo-1513104890138-7c749659a591?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-30-bagel-salmone-creamcheese', 'New York Bagel Tostato Salmone e Cream Cheese', 'sgarro', 5, 'Facile', ARRAY['Tostapane o Piastra']::TEXT[], ARRAY['1 Bagel artigianale con semi di sesamo', '60g Formaggio spalmabile tipo Philadelphia intero', '70g Salmone affumicato norvegese', 'Qualche anello di cipolla rossa e capperi']::TEXT[], ARRAY['Taglia il bagel a metà e tosta le facce interne finché sono calde e croccanti.', 'Spalma uno strato spesso di cream cheese su entrambe le metà.', 'Adagia il salmone affumicato, anelli di cipolla e capperi, quindi richiudi.']::TEXT[], 530, 26, 48, 26, 'https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-31-tiramisu-tradizionale', 'Tiramisù Tradizionale Trevigiano al Mascarpone (Monoporzione)', 'sgarro', 15, 'Facile', ARRAY['Coppetta da dessert', 'Sbattitore o Frusta', 'Moka']::TEXT[], ARRAY['4 Biscotti Savoiardi', '100g Mascarpone fresco autentico', '1 Tuorlo d''uovo freschissimo', '20g Zucchero semolato', '1 tazzina di Caffè espresso amaro e cacao amaro in polvere']::TEXT[], ARRAY['Monta il tuorlo con lo zucchero finché diventa chiaro e spumoso, poi incorpora delicatamente il mascarpone fino a crema setosa.', 'Inzuppa rapidamente i savoiardi nel caffè tiepido.', 'Alterna nella coppetta strati di savoiardi e crema di mascarpone.', 'Spolvera la superficie con abbondante cacao amaro e lascia riposare in frigo 1 ora prima di affondare il cucchiaio.']::TEXT[], 580, 11, 48, 38, 'https://images.unsplash.com/photo-1571877227200-a0d98ea607e9?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-32-french-toast-nutella-rollups', 'Nutella French Toast Roll-Ups Croccanti allo Zucchero e Cannella', 'sgarro', 10, 'Facile', ARRAY['Padella antiaderente', 'Matterello']::TEXT[], ARRAY['3 Fette di pancarré bianco senza crosta', '60g Nutella generosa', '1 Uovo sbattuto con 20ml latte', '15g Burro, zucchero e cannella per rotolare']::TEXT[], ARRAY['Appiattisci le fette di pane col matterello fino a renderle sottili.', 'Spalma abbondante Nutella su ogni fetta e arrotola stretto a cannolo.', 'Passa i rotolini nell''uovo sbattuto e falli dorare nel burro fuso in padella per 3 minuti.', 'Rotola immediatamente nello zucchero e cannella e gusta col cuore di cioccolato fuso che cola.']::TEXT[], 620, 12, 74, 31, 'https://images.unsplash.com/photo-1484723091739-0045615eb40f?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-33-brownies-fudgy-cioccolato', 'Fudgy Brownie al Cioccolato Fondente e Noci', 'sgarro', 25, 'Facile', ARRAY['Teglia quadrata 20x20', 'Pentolino per bagnomaria', 'Frusta']::TEXT[], ARRAY['100g Cioccolato fondente 70%', '60g Burro', '70g Zucchero', '2 Uova intere', '35g Farina 00 e gherigli di noce']::TEXT[], ARRAY['Fondi il cioccolato con il burro a bagnomaria o nel microonde.', 'Sbatti le uova con lo zucchero, unisci il cioccolato fuso e incorpora la farina e le noci con una spatola.', 'Versa nella teglia rivestita di carta forno e inforna a 175°C per 18-20 minuti: l''interno deve rimanere umido e scioglievole.']::TEXT[], 490, 8, 48, 30, 'https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-34-torta-tenerina-ferrarese', 'Torta Tenerina Ferrarese al Cuore Morbido Fondente', 'sgarro', 25, 'Facile', ARRAY['Tortiera da 20cm', 'Sbattitore elettrico']::TEXT[], ARRAY['120g Cioccolato fondente', '60g Burro', '2 Uova (tuorli e albumi separati)', '60g Zucchero e 25g Farina']::TEXT[], ARRAY['Fondi cioccolato e burro insieme.', 'Monta i tuorli con metà zucchero e gli albumi a neve ferma con l''altra metà.', 'Unisci il cioccolato ai tuorli, aggiungi la farina e infine incorpora gli albumi montati con movimenti dal basso verso l''alto.', 'Inforna a 170°C per 18 minuti creando la classica crosticina sottile sopra e il cuore tenerissimo sotto.']::TEXT[], 520, 9, 49, 33, 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-35-crepes-nutella-nocciole', 'Crepes alla Nutella con Granella di Nocciole Tostate', 'sgarro', 12, 'Facile', ARRAY['Crepiera o padella antiaderente', 'Frusta a mano']::TEXT[], ARRAY['1 Uovo intero', '50g Farina 00', '100ml Latte intero', '10g Burro fuso', '50g Nutella e granella di nocciole']::TEXT[], ARRAY['Sbatti l''uovo con il latte e la farina fino a pastella liquida senza grumi.', 'Cuoci le crepes in padella imburrata calda per 1 minuto per lato.', 'Farcisci con Nutella calda a volontà, piega a ventaglio o a triangolo e cospargi con granella di nocciole tostate.']::TEXT[], 560, 12, 62, 30, 'https://images.unsplash.com/photo-1519676867240-f03562e64548?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-36-waffle-panna-fragole', 'Waffle Belga con Nuvola di Panna e Fragole Fresche', 'sgarro', 12, 'Facile', ARRAY['Piastra per waffle', 'Ciotola']::TEXT[], ARRAY['1 Waffle belga dorato e caldo', '50g Panna fresca montata con vaniglia', '5 Fragole fresche a spicchi', 'Sciroppo d''acero o topping al cioccolato']::TEXT[], ARRAY['Scalda il waffle nella piastra finché è ben caldo e croccante sui nidi.', 'Decora la superficie con una generosa nuvola di panna montata fresca.', 'Aggiungi le fragole a fette e cola abbondante sciroppo d''acero.']::TEXT[], 480, 7, 56, 26, 'https://images.unsplash.com/photo-1506084868230-bb9d95c24759?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-37-cheesecake-caramello-salato', 'Cheesecake Espresso nel Bicchiere al Caramello Salato', 'sgarro', 10, 'Facile', ARRAY['Bicchiere da dessert', 'Cucchiaio']::TEXT[], ARRAY['40g Biscotti Digestive o Lotus Biscoff sbriciolati', '15g Burro fuso', '100g Formaggio fresco Philadelphia intero', '30g Panna fresca montata con zucchero a velo', '2 cucchiai di Salsa al Caramello salato']::TEXT[], ARRAY['Mischia i biscotti sbriciolati col burro fuso e pressa sul fondo del bicchiere.', 'Lavora il Philadelphia con lo zucchero a velo e incorpora la panna.', 'Versa la crema sui biscotti e corona con una colata generosa di caramello salato tiepido.']::TEXT[], 590, 8, 52, 39, 'https://images.unsplash.com/photo-1524351199679-46cddf530c04?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-38-salame-al-cioccolato', 'Salame al Cioccolato Tradizionale Senza Cottura', 'sgarro', 15, 'Facile', ARRAY['Ciotola', 'Carta forno', 'Frigo']::TEXT[], ARRAY['100g Biscotti secchi tipo Oro Saiwa', '60g Burro morbido a pomata', '60g Cioccolato fondente fuso', '30g Zucchero e 15g cacao amaro']::TEXT[], ARRAY['Spezza i biscotti con le mani in pezzi irregolari.', 'In una ciotola mescola il burro con il cioccolato fuso, lo zucchero e il cacao.', 'Unisci i biscotti all''impasto, dai la forma di un salame avvolgendolo stretto nella carta forno e lascialo rassodare in frigo 2 ore prima di tagliarlo a fette.']::TEXT[], 480, 6, 58, 26, 'https://images.unsplash.com/photo-1587314168485-3236d6710814?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-39-mousse-cioccolato-soffice', 'Mousse al Cioccolato Soffice (2 Ingredienti Tradizionale)', 'sgarro', 12, 'Facile', ARRAY['Sbattitore elettrico', 'Ciotole']::TEXT[], ARRAY['100g Cioccolato fondente 65%', '2 Uova freschissime intere (separate)', '1 pizzico di sale']::TEXT[], ARRAY['Sciogli il cioccolato a bagnomaria e fallo intiepidire.', 'Unisci i due tuorli al cioccolato uno alla volta mescolando.', 'Monta gli albumi a neve fermissima con il pizzico di sale e incorporali delicatamente senza smontare il composto.', 'Riponi in frigo per 2 ore: diventerà una spuma aerata e vellutata.']::TEXT[], 410, 12, 32, 27, 'https://images.unsplash.com/photo-1551024709-8f23befc6f87?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-40-calzone-fritto-ricotta-cioccolato', 'Calzone Dolce Fritto con Ricotta di Pecora e Cioccolato', 'sgarro', 15, 'Facile', ARRAY['Padella per friggere', 'Forchetta']::TEXT[], ARRAY['1 Panetto di pasta pizza (120g)', '80g Ricotta di pecora zuccherata', '30g Gocce di cioccolato fondente', 'Zucchero a velo per guarnire']::TEXT[], ARRAY['Stendi la pasta a disco e farcisci metà disco con la ricotta mescolata al cioccolato.', 'Chiudi a mezzaluna sigillando accuratamente i bordi con la forchetta.', 'Friggi in olio caldo per 2-3 minuti fino a doratura uniforme e spolvera generosamente di zucchero a velo.']::TEXT[], 590, 16, 68, 28, 'https://images.unsplash.com/photo-1513104890138-7c749659a591?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-41-cinnamon-rolls-glassa', 'Cinnamon Roll Espressi Caldi con Glassa alla Vaniglia', 'sgarro', 20, 'Facile', ARRAY['Teglia da forno', 'Pennellino']::TEXT[], ARRAY['1 Rotolo di pasta sfoglia rettangolare', '30g Burro fuso', '35g Zucchero di canna + 1 cucchiaio colmo di Cannella', 'Glassa: 40g zucchero a velo + 1 cucchiaio latte']::TEXT[], ARRAY['Spennella la sfoglia con il burro fuso e cospargi con lo zucchero di canna e la cannella.', 'Arrotola stretto per il lato lungo e taglia rondelle spesse 2-3 cm.', 'Disponi su teglia e inforna a 190°C per 15 minuti finché sono dorate e caramellate. Cola sopra la glassa calda.']::TEXT[], 540, 6, 64, 29, 'https://images.unsplash.com/photo-1509440159596-0249088772ff?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-42-crostata-marmellata-ciliegie', 'Crostata Friabile della Nonna alla Confettura di Ciliegie', 'sgarro', 30, 'Facile', ARRAY['Stampo per crostate da 22cm', 'Forno']::TEXT[], ARRAY['1 Rotolo di pasta frolla pronta al burro', '180g Confettura extra di ciliegie o visciole']::TEXT[], ARRAY['Fodera lo stampo con la frolla tenendo da parte i ritagli per le strisce.', 'Spalma la confettura di ciliegie livellando con un cucchiaio.', 'Forma la classica griglia con le losanghe di pasta e inforna a 180°C per 25 minuti fino a doratura biscottata.']::TEXT[], 480, 5, 72, 19, 'https://images.unsplash.com/photo-1519869325930-281384150729?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-43-tortino-cuore-caldo', 'Tortino al Cioccolato con Cuore Caldo Fondente', 'sgarro', 18, 'Medio', ARRAY['Pirottini in alluminio monoporzione', 'Forno statico']::TEXT[], ARRAY['80g Cioccolato fondente', '40g Burro', '1 Uovo intero', '30g Zucchero semolato', '15g Farina 00']::TEXT[], ARRAY['Fondi cioccolato e burro a bagnomaria.', 'Monta l''uovo con lo zucchero, unisci il cioccolato fuso intiepidito e la farina setacciata.', 'Imburra il pirottino, cospargilo di cacao amaro, versa il composto e inforna a 190°C per esattamente 10 minuti.', 'Sforma su un piattino: l''esterno sarà una tortina soffice e l''interno una fontana di cioccolato fuso bollente.']::TEXT[], 510, 7, 46, 34, 'https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-44-banana-split-suprema', 'Banana Split Americana Tradizionale con Triplo Gelato', 'sgarro', 5, 'Facile', ARRAY['Piatto lungo da banana split', 'Porzionatore gelato']::TEXT[], ARRAY['1 Banana matura sbucciata e tagliata a metà per lungo', '3 Palline di gelato (vaniglia, cioccolato, fragola)', '40g Panna montata spray', 'Cioccolato fondente fuso e ciliegina candita']::TEXT[], ARRAY['Disponi le due metà della banana sui lati del piatto.', 'Posiziona al centro le tre palline di gelato.', 'Copri con ciuffi generosi di panna montata, cola il cioccolato fuso a filo e incorona con la ciliegina.']::TEXT[], 560, 8, 78, 25, 'https://images.unsplash.com/photo-1563805042-7684c019e1cb?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-45-churros-spagnoli', 'Churros Caldi Zuccherati con Cioccolata Calda Densa', 'sgarro', 20, 'Facile', ARRAY['Sac à poche con beccuccio a stella', 'Padella per friggere']::TEXT[], ARRAY['120g Farina 00', '150ml Acqua con 20g burro e un pizzico di sale', 'Olio per friggere', 'Zucchero semolato, cannella e tazza di cioccolata calda densa']::TEXT[], ARRAY['Porta a ebollizione l''acqua con il burro, butta la farina tutta insieme e mescola finché l''impasto si stacca dalle pareti della pentola.', 'Metti l''impasto nella sac à poche e spremi cordoni di pasta nell''olio bollente tagliandoli con una forbice.', 'Friggi 3 minuti fino a doratura croccante, rotola nello zucchero e cannella e intingi nella cioccolata.']::TEXT[], 530, 7, 70, 26, 'https://images.unsplash.com/photo-1624300629298-e9de39c13be5?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-46-cookies-pepite-cioccolato', 'Maxi Cookies Americani Morbidi con Chunks di Cioccolato', 'sgarro', 18, 'Facile', ARRAY['Teglia da forno', 'Carta forno', 'Ciotola']::TEXT[], ARRAY['100g Farina 00', '50g Burro morbido', '40g Zucchero di canna', '1 Tuorlo d''uovo', '50g Cioccolato fondente a pezzi grossolani']::TEXT[], ARRAY['Lavora il burro con lo zucchero fino a crema, unisci il tuorlo e infine la farina e i grossi pezzi di cioccolato.', 'Forma 3 o 4 palline grandi e disponile ben distanziate sulla teglia.', 'Inforna a 180°C per 10-12 minuti: toglili appena i bordi dorano anche se il centro sembra morbido (diventeranno perfetti raffreddandosi).']::TEXT[], 540, 7, 64, 29, 'https://images.unsplash.com/photo-1558961363-fa8fdf82db35?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-47-sbriciolata-nutella', 'Sbriciolata Golosa alla Nutella Senza Cottura', 'sgarro', 12, 'Facile', ARRAY['Stampo a cerniera da 18cm', 'Ciotola', 'Frigo']::TEXT[], ARRAY['150g Biscotti secchi al cioccolato o Pan di Stelle', '60g Burro fuso', '120g Nutella leggermente scaldata']::TEXT[], ARRAY['Trita grossolanamente i biscotti e unisci il burro fuso.', 'Versa metà dei biscotti nello stampo compattando la base con il dorso del cucchiaio.', 'Colaci sopra tutta la Nutella calda e ricopri con il resto dei biscotti sbriciolati.', 'Lascia rassodare in frigo per 45 minuti e taglia a quadrotti golosissimi.']::TEXT[], 640, 8, 70, 37, 'https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-48-affogato-caffe-gelato', 'Affogato al Caffè con Gelato alla Vaniglia e Panna', 'sgarro', 3, 'Facile', ARRAY['Coppa di vetro', 'Moka o macchina espresso']::TEXT[], ARRAY['2 Palline generose di gelato alla vaniglia artigianale o fior di latte', '1 Tazzina di caffè espresso bollente appena estratto', 'Ciuffo di Panna montata e scaglie di cioccolato']::TEXT[], ARRAY['Metti le due palline di gelato freddissimo nella coppa.', 'Versa l''espresso bollente direttamente sopra il gelato, ammirando il contrasto caldo-freddo che scioglie parzialmente la crema.', 'Completa con panna e scaglie di cioccolato e gusta subito con il cucchiaino.']::TEXT[], 340, 5, 36, 20, 'https://images.unsplash.com/photo-1571877227200-a0d98ea607e9?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-49-apple-crumble-cannella', 'Apple Crumble Caldo alle Mele con Burro e Cannella', 'sgarro', 25, 'Facile', ARRAY['Pirofila monoporzione da forno', 'Forno']::TEXT[], ARRAY['1 Mela Golden sbucciata a tocchetti', '1 cucchiaino di Cannella e 1 cucchiaio zucchero di canna', '40g Farina 00', '25g Burro freddo a cubetti']::TEXT[], ARRAY['Disponi i cubetti di mela nella pirofila mescolati con cannella e un cucchiaino di zucchero.', 'Lavora con la punta delle dita la farina, il burro freddo e il restante zucchero fino a briciole sabbiose.', 'Copri le mele con le briciole e inforna a 190°C per 20 minuti finché il crumble è croccante e dorato e le mele borbottano caramellate.']::TEXT[], 430, 4, 62, 20, 'https://images.unsplash.com/photo-1568571780765-9276ac8b75a2?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-50-cannoli-siciliani', 'Cannolo Siciliano Espresso alla Ricotta e Pistacchio', 'sgarro', 5, 'Facile', ARRAY['Sac à poche o cucchiaino', 'Piatto da portata']::TEXT[], ARRAY['2 Cialde di cannolo siciliano croccanti pronte', '120g Crema di ricotta di pecora zuccherata', 'Granella di Pistacchio di Bronte e gocce di cioccolato', 'Zucchero a velo']::TEXT[], ARRAY['Farcisci le cialde di cannolo con la ricotta solo all''ultimo momento per mantenere la cialda croccantissima.', 'Intingi un''estremità nella granella di pistacchio e l''altra nelle gocce di cioccolato.', 'Spolvera con zucchero a velo e gusta la regina della pasticceria siciliana.']::TEXT[], 510, 12, 54, 28, 'https://images.unsplash.com/photo-1551024709-8f23befc6f87?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-51-profiteroles-cioccolato', 'Profiteroles al Cioccolato con Panna Soffice', 'sgarro', 12, 'Facile', ARRAY['Coppa da dessert', 'Frusta']::TEXT[], ARRAY['4 Bignè di pasta choux pronti', '60g Panna fresca montata zuccherata', '70g Glassa calda al cioccolato fondente (cioccolato fuso con un goccio di panna)']::TEXT[], ARRAY['Pratica un piccolo foro sul fondo dei bignè e farciscili generosamente con la panna montata.', 'Impila i bignè a piramide nella coppa da dessert.', 'Cola sopra la glassa tiepida al cioccolato ricoprendoli interamente.']::TEXT[], 490, 7, 42, 34, 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=600&q=80'),
  ('sgarro-52-fetta-paradiso-nutella', 'Torta Fetta al Latte e Nutella Soffice come una Nuvola', 'sgarro', 15, 'Facile', ARRAY['Tagliere', 'Spatola']::TEXT[], ARRAY['2 Fette spesse di pan di spagna al cacao morbido', '60g Crema al latte (panna montata con latte condensato e miele)', '30g Nutella a strato']::TEXT[], ARRAY['Adagia la prima fetta di pan di spagna sul piatto.', 'Spalma un sottile strato di Nutella e copri con la crema soffice al latte alta 2 cm.', 'Chiudi con la seconda fetta, lascia in frigo 30 minuti e taglia a trancetti rettangolari.']::TEXT[], 460, 7, 54, 24, 'https://images.unsplash.com/photo-1578985545062-69928b1d9587?auto=format&fit=crop&w=600&q=80')
